type View='overview'|'requirements'|'development'|'quality'|'operations'|'knowledge'|'settings';
const nav:{id:View;label:string;icon:typeof Home}[]=[{id:'overview',label:'项目概览',icon:Home},{id:'requirements',label:'需求规划',icon:Layers},{id:'development',label:'开发协作',icon:Code2},{id:'quality',label:'质量验收',icon:ShieldCheck},{id:'operations',label:'发布运维',icon:Box},{id:'knowledge',label:'知识空间',icon:BookOpen},{id:'settings',label:'项目设置',icon:Settings}];
